function WeekTasksRewardPreviewDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local len = #self.rewards
        while len ~= table.count(self.indexes) do
            CoYield()
        end
        self.ListView.ContainerTrans:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, self.contentHeight)
    end))
    return coWait
end

function WeekTasksRewardPreviewDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.WeekGachapon.WeekTasksRewardCellNode")
    if nodeEnv then
        local luaIndex = index + 1
        local rewardData = self.rewards[luaIndex]
        local title = self.titleList[luaIndex]
        nodeEnv:FreshTitle(title)
        nodeEnv:FreshGoodsList(rewardData)
        local rectTrans = KTool.GetComponent(cell.gameObject, typeof(RectTransform))
        CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(rectTrans)
        if not self.indexes[tostring(luaIndex)] then
            self.indexes[tostring(luaIndex)] = luaIndex
            self.contentHeight = self.contentHeight + rectTrans.sizeDelta.y
        end
    end
    return cell
end

function WeekTasksRewardPreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return WeekTasksRewardPreviewDialog